/*
 * A320927  Concatenation of successive segments generated by the morphism {0
 *          -> {0, 0, 1}, 1 -> {0,1,0}}, starting with 0.
 * https://oeis.org/A320927
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the nth term of the concatenation of successively
 *            applied morphisms 0 -> {0,0,1}, 1 -> {0,1,0}, starting from 0
 * Range:     u8 n <= 9276, u16 n <= 9276, u32 n <= 9276, u64 n <= 9276,
 *            u128 n <= 9276, big any n
 * Helpers:   _seg_val
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/_seg_val.h"

seq_t a(idx_t n)
{
    /* Segment lengths follow 3^k.  Find the segment that contains n. */
    idx_t cumulative = 0;          /* total length of all previous segments */
    idx_t length     = 1;          /* length of the current segment (3^k) */
    idx_t k          = 0;          /* current segment index */

    while (cumulative + length < n) {
        cumulative += length;
        length     *= 3;
        k++;
    }

    /* Position within the chosen segment (0‑based). */
    idx_t pos = n - cumulative - 1;
    return _seg_val(k, pos);
}
